import { connection } from 'next/server'

import { toggleNotifications } from '@/app/actions'
import { getNotificationPreference } from '@/app/lib/notification-preferences'
import { SubmitButton } from '@/app/submit-button'

export default async function Home() {
  // Opt out of static prerendering so the preference is read on every request.
  // `refresh()` refreshes the page's *dynamic* data, so this read has to be
  // dynamic for the toggled value to come back after the action runs.
  await connection()

  const enabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>

      <p>
        Notifications are <strong>{enabled ? 'on' : 'off'}</strong>.
      </p>

      <form action={toggleNotifications}>
        <SubmitButton>{enabled ? 'Turn off' : 'Turn on'}</SubmitButton>
      </form>
    </main>
  )
}

